-- ════════════════════════════════════════════════════════
-- 316 — Le lexique passe de 56 à 86 termes
-- ────────────────────────────────────────────────────────
-- CE QU'ON A TROUVÉ. Suite du chantier lexique (31 octobre 2026) : 30 termes de plus, sur les thèmes que le lecteur
-- cherche après la fabrication et la dégustation : conservation (moisissure, remise en état, acclimatation,
-- humidificateur, humidité relative, quarantaine, vieillissement), authenticité (code de boîte, numéro de série,
-- contrefaçon), variétés de tabac (Corojo, Criollo, Habano 2000, Connecticut shade, Sumatra, Havana Seed, Cubano,
-- Pelo de Oro) et fabrication (palillo, escogida, curado, rezago, ligada).
-- 1. Chaque définition tient en deux phrases et ne cite aucun prix, aucune marque en vente, aucune parole rapportée.
--    Les chiffres sont des ordres de grandeur d'usage (humidité 65-72 %, calibre en 64e de pouce) et les dires de
--    Habanos sont attribués (édition limitée).
-- 2. Les variantes sont des chaînes littérales françaises (la détection se fait sur le français). On évite les mots
--    trop courants (« tête », « pied », « corona ») qui allumeraient une glose au mauvais endroit.
-- 3. Traductions en cinq langues, scellées « machine » dans translation_status.
-- ════════════════════════════════════════════════════════

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'moisissure', 'conservation', 'moisissure|moisissures|moisi|moisis', 'Moisissure', 'Duvet de champignons qui apparaît sur la cape ou le pied d''un cigare gardé trop humide, souvent blanc, vert ou bleuâtre, avec une odeur de moisi. Elle se distingue de la plume, dépôt cristallin sec qui s''enlève à la brosse.', 'Mould', 'A fuzzy fungal growth that appears on the wrapper or foot of a cigar kept too damp, often white, green or bluish and with a musty smell. It differs from bloom, a dry crystalline deposit that brushes off.', 'Moho', 'Un velo de hongos que aparece en la capa o en el pie de un puro guardado con demasiada humedad, a menudo blanco, verde o azulado y con olor a moho. Se distingue del bloom, un depósito cristalino seco que sale con un cepillo.', 'Schimmel', 'Ein flaumiger Pilzbelag auf Deckblatt oder Fuß einer zu feucht gelagerten Zigarre, oft weiß, grün oder bläulich und mit muffigem Geruch. Er unterscheidet sich vom Bloom, einer trockenen kristallinen Ablagerung, die man mit einer Bürste entfernen kann.', '霉菌', '存放过湿的雪茄在外包叶或脚部长出的绒毛状真菌，常呈白色、绿色或泛蓝，并带有霉味。它不同于烟霜（bloom）：后者是干燥的结晶沉积物，可以刷掉。', 'العفن', 'نموّ فطري زغبي يظهر على الورقة الخارجية أو قدم سيجار حُفظ في رطوبة زائدة، وهو غالبًا أبيض أو أخضر أو مائل إلى الزرقة ورائحته عفنة. ويختلف عن الزهر (bloom) وهو ترسّب بلوري جاف يزول بالفرشاة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'moisissure');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'remise-en-etat', 'conservation', 'remise en état|réhumidification|réhumidifier|cigare desséché|cigares desséchés', 'Remise en état', 'Le retour progressif à un taux d''humidité normal d''un cigare qui a séché. On le fait sur plusieurs semaines, dans un humidor réglé bas puis remonté peu à peu, car une reprise brutale fend la cape.', 'Rehumidifying', 'Bringing a cigar that has dried out back to a normal moisture level step by step. It is done over several weeks in a humidor set low and raised gradually, because abrupt rehumidifying splits the wrapper.', 'Rehumidificación', 'El regreso gradual a un nivel de humedad normal de un puro que se ha secado. Se hace durante varias semanas, en un humidor ajustado bajo y subido poco a poco, porque una rehidratación brusca raja la capa.', 'Rehydratisierung', 'Die schrittweise Rückführung einer ausgetrockneten Zigarre auf einen normalen Feuchtegehalt. Sie erfolgt über mehrere Wochen in einem zunächst niedrig eingestellten, dann langsam angehobenen Humidor, denn abruptes Befeuchten lässt das Deckblatt reißen.', '回潮复原', '让变干的雪茄逐步恢复到正常含水量。通常在先调低、再慢慢提高湿度的雪茄盒中进行，历时数周，因为骤然加湿会使外包叶开裂。', 'إعادة الترطيب', 'إعادة سيجار جفّ إلى مستوى رطوبته المعتاد تدريجيًا. تتم على مدى عدة أسابيع في صندوق حفظ يُضبط على رطوبة منخفضة ثم تُرفع شيئًا فشيئًا، لأن الترطيب المفاجئ يشقّ الورقة الخارجية.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'remise-en-etat');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'acclimatation', 'conservation', 'acclimatation|acclimater|acclimatement', 'Acclimatation', 'Le temps de repos laissé à un cigare qui vient de voyager ou de changer d''humidor, de quelques jours à quelques semaines. Il retrouve ainsi une humidité homogène avant d''être fumé.', 'Acclimatisation', 'The resting time given to a cigar that has just travelled or moved to another humidor, from a few days to a few weeks. It regains an even moisture level before being smoked.', 'Aclimatación', 'El tiempo de reposo que se da a un puro que acaba de viajar o de cambiar de humidor, de unos días a unas semanas. Así recupera una humedad homogénea antes de fumarse.', 'Akklimatisierung', 'Die Ruhezeit für eine Zigarre, die gerade gereist oder in einen anderen Humidor umgezogen ist, von einigen Tagen bis zu einigen Wochen. So findet sie vor dem Rauchen zu einer gleichmäßigen Feuchte zurück.', '适应期', '刚经过运输或换到另一个雪茄盒的雪茄所需的静置时间，从几天到几周不等。这样它在抽吸前能恢复均匀的湿度。', 'التأقلم', 'مدة الراحة التي تُعطى لسيجار وصل لتوّه من سفر أو انتقل إلى صندوق حفظ آخر، من أيام قليلة إلى أسابيع. وبذلك تعود إليه رطوبة متجانسة قبل تدخينه.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'acclimatation');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'humidite-relative', 'conservation', 'humidité relative|taux d''humidité|hygrométrie', 'Humidité relative', 'Le taux d''humidité de l''air de l''humidor, exprimé en pourcentage. Le repère courant va de 65 à 72 % ; Habanos indique 65 à 70 %, et 69 à 72 % est une plage fréquente dans les conseils d''usage, avec une température d''environ 18 à 21 °C.', 'Relative humidity', 'The moisture content of the humidor''s air, expressed as a percentage. The usual guide runs from 65 to 72%; Habanos gives 65 to 70%, and 69 to 72% is a common range in practical advice, at a temperature of about 18 to 21 °C.', 'Humedad relativa', 'El grado de humedad del aire del humidor, expresado en porcentaje. La referencia habitual va del 65 al 72 %; Habanos indica del 65 al 70 %, y del 69 al 72 % es un intervalo frecuente en los consejos prácticos, con una temperatura de unos 18 a 21 °C.', 'Relative Luftfeuchtigkeit', 'Der Feuchtegehalt der Luft im Humidor, in Prozent angegeben. Als Richtwert gelten 65 bis 72 %; Habanos nennt 65 bis 70 %, und 69 bis 72 % ist in praktischen Ratschlägen ein gängiger Bereich, bei einer Temperatur von etwa 18 bis 21 °C.', '相对湿度', '雪茄盒内空气的含水程度，以百分比表示。常见参考值为65%至72%；Habanos给出的是65%至70%，而69%至72%是实用建议中常见的区间，温度约18至21摄氏度。', 'الرطوبة النسبية', 'نسبة الرطوبة في هواء صندوق الحفظ، معبَّرًا عنها بالمئة. المرجع الشائع بين 65 و72 %؛ وتذكر «هابانوس» 65 إلى 70 %، ويتردد مجال 69 إلى 72 % في النصائح العملية، مع حرارة تبلغ نحو 18 إلى 21 درجة مئوية.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'humidite-relative');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'humidificateur', 'conservation', 'humidificateur|humidificateurs|propylène glycol|éponge humidificatrice', 'Humidificateur', 'L''élément de l''humidor qui libère la vapeur d''eau : mousse, gel ou cristaux, chargé d''eau distillée ou d''une solution de propylène glycol. Il se vérifie et se recharge selon la lecture de l''hygromètre.', 'Humidifier', 'The part of the humidor that releases water vapour: foam, gel or crystals, charged with distilled water or a propylene glycol solution. It is checked and refilled according to the hygrometer reading.', 'Humidificador', 'El elemento del humidor que libera vapor de agua: espuma, gel o cristales, cargado con agua destilada o con una solución de propilenglicol. Se revisa y se rellena según la lectura del higrómetro.', 'Befeuchter', 'Das Element des Humidors, das Wasserdampf abgibt: Schaumstoff, Gel oder Kristalle, mit destilliertem Wasser oder einer Propylenglykol-Lösung gefüllt. Er wird nach dem Hygrometerwert kontrolliert und nachgefüllt.', '加湿器', '雪茄盒中释放水汽的部件，有海绵、凝胶或晶体几种，注入蒸馏水或丙二醇溶液。应根据湿度计读数检查并补充。', 'المرطّب', 'الجزء من صندوق الحفظ الذي يطلق بخار الماء: إسفنج أو هلام أو بلورات، يُملأ بماء مقطّر أو بمحلول بروبيلين غليكول. يُفحص ويُعاد ملؤه بحسب قراءة مقياس الرطوبة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'humidificateur');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'quarantaine', 'conservation', 'quarantaine|mise en quarantaine', 'Quarantaine', 'Le séjour à part, de quelques semaines, d''un cigare nouvellement acquis avant de le ranger avec les autres. Il permet de repérer une moisissure ou des trous de ver du tabac sans les propager.', 'Quarantine', 'Keeping a newly acquired cigar apart for a few weeks before storing it with the others. It makes it possible to spot mould or tobacco beetle holes without spreading them.', 'Cuarentena', 'La estancia aparte, de unas semanas, de un puro recién adquirido antes de guardarlo con los demás. Permite detectar moho o agujeros de gorgojo del tabaco sin propagarlos.', 'Quarantäne', 'Die mehrwöchige Separatlagerung einer neu erworbenen Zigarre, bevor sie zu den anderen gelegt wird. So lassen sich Schimmel oder Fraßlöcher des Tabakkäfers erkennen, ohne sie zu verbreiten.', '隔离观察', '新买的雪茄在与其他雪茄同放之前，单独存放数周。这样可以发现霉菌或烟草甲的蛀孔，而不致扩散。', 'الحجر', 'إبقاء سيجار اشتُري حديثًا منفصلًا لبضعة أسابيع قبل وضعه مع غيره. يتيح ذلك اكتشاف العفن أو ثقوب خنفساء التبغ دون نشرها.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'quarantaine');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'vieillissement', 'conservation', 'vieillissement|cigare vieilli|cigares vieillis|añejamiento', 'Vieillissement', 'La garde prolongée d''un cigare fini, qui affine sa saveur et son arôme. Habanos la date de la fermeture de la boîte, ne fixe aucune durée minimale pour dire un cigare vieilli, et prévient qu''un cigare desséché perd en arôme.', 'Ageing', 'The prolonged keeping of a finished cigar, which can refine its flavour and aroma. Habanos counts it from the date the box was sealed, sets no minimum period for calling a cigar aged, and warns that a dried-out cigar loses aroma.', 'Añejamiento', 'La guarda prolongada de un puro terminado, que puede afinar su sabor y su aroma. Habanos la cuenta desde la fecha de cierre de la caja, no fija ningún plazo mínimo para llamar añejo a un puro y advierte de que un puro seco pierde aroma.', 'Alterung', 'Die längere Lagerung einer fertigen Zigarre, die Geschmack und Aroma verfeinern kann. Habanos rechnet ab dem Datum, an dem die Kiste verschlossen wurde, nennt keine Mindestdauer für eine gereifte Zigarre und warnt, dass eine ausgetrocknete Zigarre an Aroma verliert.', '陈放', '对成品雪茄的长期存放，可使风味和香气更为细腻。Habanos从雪茄盒封装之日算起，并未规定存放多少年才可称为陈年雪茄，同时提醒干掉的雪茄会流失香气。', 'التعتيق', 'الحفظ المطوّل لسيجار جاهز، وقد يصقل نكهته وعطره. تحتسبه «هابانوس» من تاريخ إغلاق العلبة، ولا تحدد مدة دنيا لوصف سيجار بأنه معتّق، وتنبّه إلى أن السيجار الجاف يفقد عطره.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'vieillissement');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'lasioderma', 'conservation', 'lasioderma|ver du tabac|coléoptère du tabac|cigarette beetle', 'Ver du tabac (Lasioderma)', 'Le coléoptère Lasioderma serricorne, dont la larve perce le cigare de petits trous et laisse une fine poussière. Sa reproduction est favorisée par la chaleur et l''humidité excessives de la garde.', 'Tobacco beetle', 'The beetle Lasioderma serricorne, whose larva bores small holes in the cigar and leaves a fine dust. Its breeding is encouraged by excessive warmth and humidity in storage.', 'Gorgojo del tabaco', 'El coleóptero Lasioderma serricorne, cuya larva perfora el puro con pequeños agujeros y deja un fino polvo. Su reproducción se ve favorecida por el calor y la humedad excesivos de la conservación.', 'Tabakkäfer', 'Der Käfer Lasioderma serricorne, dessen Larve kleine Löcher in die Zigarre bohrt und feinen Staub hinterlässt. Seine Vermehrung wird durch übermäßige Wärme und Feuchte bei der Lagerung begünstigt.', '烟草甲', '烟草甲（Lasioderma serricorne）是一种甲虫，其幼虫在雪茄上蛀出小孔并留下细粉。存放时过高的温度和湿度有利于它繁殖。', 'خنفساء التبغ', 'الخنفساء Lasioderma serricorne التي تثقب يرقتها السيجار بثقوب صغيرة وتترك غبارًا ناعمًا. ويساعد على تكاثرها الدفء والرطوبة المفرطان أثناء الحفظ.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'lasioderma');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'code-de-boite', 'marche', 'code de boîte|codes de boîte|code de la boîte|box code', 'Code de boîte', 'Sur une boîte de Habanos, les deux tampons d''encre du fond : un code qui indique la fabrique et la date de mise en boîte. Chiffrée de 1985 à 1999, la date est lisible depuis 2000 ; le code n''est qu''un indice, jamais une preuve d''authenticité.', 'Box code', 'On a box of Habanos, the two ink stamps on the bottom: a code showing the factory and the date of boxing. Encrypted from 1985 to 1999, the date has been readable since 2000; the code is only a clue, never proof of authenticity.', 'Código de caja', 'En una caja de Habanos, los dos sellos de tinta del fondo: un código que indica la fábrica y la fecha de encajado. Cifrada de 1985 a 1999, la fecha es legible desde 2000; el código es solo un indicio, nunca una prueba de autenticidad.', 'Kistencode', 'Auf einer Habanos-Kiste die beiden Tintenstempel am Boden: ein Code für die Fabrik und das Datum der Verpackung. Von 1985 bis 1999 war das Datum verschlüsselt, seit 2000 ist es lesbar; der Code ist nur ein Hinweis, nie ein Echtheitsbeweis.', '雪茄盒编码', 'Habanos雪茄盒底部的两枚墨印：一个标明工厂的代码，以及装盒日期。日期在1985至1999年为加密，自2000年起可直接读取；该编码只是线索，不能证明真伪。', 'رمز العلبة', 'على علبة «هابانوس»، الختمان الحبريان في القاع: رمز يدل على المصنع وتاريخ التعبئة. كان التاريخ مشفّرًا من 1985 إلى 1999 وصار مقروءًا منذ 2000؛ والرمز مجرد قرينة وليس دليلًا على الأصالة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'code-de-boite');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'numero-de-serie', 'marche', 'numéro de série|numéros de série|code-barres individuel|hologramme|hologrammes', 'Numéro de série et hologramme', 'Selon Habanos, la version de la bande de garantie introduite en 2009 porte un hologramme et un code-barres individuel qui suit chaque boîte. On peut le contrôler sur le site de Habanos, sans que cela remplace l''examen de l''ensemble de la boîte.', 'Serial number and hologram', 'According to Habanos, the version of the guarantee strip introduced in 2009 carries a hologram and an individual barcode that tracks each box. It can be checked on the Habanos website, which does not replace examining the box as a whole.', 'Número de serie y holograma', 'Según Habanos, la versión de la banda de garantía introducida en 2009 lleva un holograma y un código de barras individual que sigue cada caja. Puede comprobarse en el sitio de Habanos, sin que ello sustituya al examen del conjunto de la caja.', 'Seriennummer und Hologramm', 'Laut Habanos trägt die 2009 eingeführte Version des Garantiestreifens ein Hologramm und einen individuellen Strichcode, der jede Kiste verfolgt. Er lässt sich auf der Habanos-Website prüfen, ersetzt aber nicht die Prüfung der gesamten Kiste.', '序列号与全息图', '据Habanos介绍，2009年推出的新版防伪封条带有全息图和每盒独有的条形码，用于追踪每一盒雪茄。可在Habanos网站上核验，但这不能取代对整个雪茄盒的检查。', 'الرقم التسلسلي والهولوغرام', 'بحسب «هابانوس»، يحمل الإصدار الذي طُرح عام 2009 من شريط الضمان هولوغرامًا ورمزًا شريطيًا فرديًا يتتبّع كل علبة. ويمكن فحصه على موقع «هابانوس»، لكن ذلك لا يغني عن فحص العلبة كاملة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'numero-de-serie');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'contrefacon', 'marche', 'contrefaçon|contrefaçons|contrefait|contrefaits|faux Habanos', 'Contrefaçon', 'Un cigare ou une boîte imitant une marque pour tromper l''acheteur, souvent en copiant bandes, sceaux et boîtes de Habanos. Aucun détail isolé ne tranche : on recoupe l''emballage, le code, la bande et le cigare lui-même.', 'Counterfeit', 'A cigar or box imitating a brand to deceive the buyer, often by copying Habanos bands, seals and boxes. No single detail settles it: packaging, code, band and the cigar itself are cross-checked.', 'Falsificación', 'Un puro o una caja que imita una marca para engañar al comprador, a menudo copiando anillas, sellos y cajas de Habanos. Ningún detalle aislado decide: se cotejan el embalaje, el código, la anilla y el propio puro.', 'Fälschung', 'Eine Zigarre oder Kiste, die eine Marke nachahmt, um den Käufer zu täuschen, oft durch das Kopieren von Bauchbinden, Siegeln und Kisten von Habanos. Kein einzelnes Detail entscheidet: Verpackung, Code, Binde und die Zigarre selbst werden miteinander abgeglichen.', '仿冒品', '为欺骗买家而模仿某个品牌的雪茄或雪茄盒，常常复制Habanos的烟标、封条和盒子。单凭一处细节无法判定，需要把包装、编码、烟标和雪茄本身相互对照。', 'التزييف', 'سيجار أو علبة تقلّد علامة تجارية لخداع المشتري، وكثيرًا ما تنسخ حلقات «هابانوس» وأختامها وعلبها. لا يحسم الأمر تفصيل واحد، بل تُقارن العبوة والرمز والحلقة والسيجار نفسه.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'contrefacon');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'marque-homonyme', 'marche', 'marque homonyme|marques homonymes|homonyme cubain|homonymes cubains', 'Marque homonyme', 'Une marque non cubaine qui porte le même nom qu''une marque cubaine. Après les nationalisations de 1960, plusieurs noms ont été repris hors de Cuba, de sorte qu''un même nom désigne deux produits distincts selon le pays de roulage.', 'Namesake brand', 'A non-Cuban brand that carries the same name as a Cuban brand. After the nationalisations of 1960, several names were taken up outside Cuba, so the same name designates two distinct products depending on the country of manufacture.', 'Marca homónima', 'Una marca no cubana que lleva el mismo nombre que una marca cubana. Tras las nacionalizaciones de 1960, varios nombres se retomaron fuera de Cuba, de modo que un mismo nombre designa dos productos distintos según el país de elaboración.', 'Namensgleiche Marke', 'Eine nichtkubanische Marke, die denselben Namen wie eine kubanische trägt. Nach den Verstaatlichungen von 1960 wurden mehrere Namen außerhalb Kubas weitergeführt, sodass derselbe Name je nach Herstellungsland zwei verschiedene Produkte bezeichnet.', '同名品牌', '与某个古巴品牌同名的非古巴品牌。1960年国有化之后，若干名称在古巴境外被继续使用，于是同一个名字会因制造国不同而指向两种不同的产品。', 'العلامة المتجانسة الاسم', 'علامة غير كوبية تحمل الاسم نفسه الذي تحمله علامة كوبية. فبعد التأميمات عام 1960 استُعملت أسماء عدة خارج كوبا، فصار الاسم الواحد يدل على منتجين مختلفين بحسب بلد الصنع.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'marque-homonyme');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'corojo', 'feuille', 'corojo|corojos', 'Corojo', 'Variété d''origine cubaine, cultivée en plein soleil et employée pour la cape. Délaissée à Cuba au profit d''hybrides résistants au moho azul, elle survit surtout par des semences dérivées cultivées en Amérique centrale.', 'Corojo', 'A variety of Cuban origin, grown in full sun and used for wrappers. Set aside in Cuba in favour of hybrids resistant to blue mould, it survives mostly through derived seeds grown in Central America.', 'Corojo', 'Variedad de origen cubano, cultivada a pleno sol y empleada para la capa. Dejada de lado en Cuba en favor de híbridos resistentes al moho azul, pervive sobre todo en semillas derivadas cultivadas en Centroamérica.', 'Corojo', 'Eine Sorte kubanischen Ursprungs, die in voller Sonne wächst und für das Deckblatt dient. In Kuba zugunsten schimmelresistenter Hybriden gegen den Blauschimmel aufgegeben, lebt sie vor allem in abgeleiteten Samen weiter, die in Mittelamerika angebaut werden.', '科罗霍', '起源于古巴的品种，在全日照下种植，用作外包叶。古巴为抗霜霉病（moho azul）而改种杂交品种后，它主要靠中美洲种植的衍生种子延续。', 'كوروخو', 'صنف كوبي الأصل يُزرع تحت الشمس الكاملة ويُستعمل للورقة الخارجية. تخلّت عنه كوبا لصالح هجن مقاومة للعفن الأزرق، ويستمر خصوصًا عبر بذور مشتقة تُزرع في أمريكا الوسطى.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'corojo');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'criollo', 'feuille', 'criollo|criollos|criollo ''98|criollo 98', 'Criollo', 'Variété d''origine cubaine, employée pour la tripe et la sous-cape. Le Criollo ''98 est une lignée dérivée, apparue à Cuba, que l''on cultive aussi en Amérique centrale.', 'Criollo', 'A variety of Cuban origin, used for filler and binder. Criollo ''98 is a derived line that appeared in Cuba and is also grown in Central America.', 'Criollo', 'Variedad de origen cubano, empleada para la tripa y la subcapa. El Criollo ''98 es una línea derivada, surgida en Cuba, que también se cultiva en Centroamérica.', 'Criollo', 'Eine Sorte kubanischen Ursprungs, die für Einlage und Umblatt verwendet wird. Criollo ''98 ist eine abgeleitete Linie, die in Kuba entstand und auch in Mittelamerika angebaut wird.', '克里奥罗', '起源于古巴的品种，用于叶芯和束叶。Criollo ''98是在古巴出现的衍生品系，中美洲也有种植。', 'كريولو', 'صنف كوبي الأصل يُستعمل للحشوة والغلاف الداخلي. أما «كريولو 98» فسلالة مشتقة ظهرت في كوبا وتُزرع أيضًا في أمريكا الوسطى.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'criollo');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'habano-2000', 'feuille', 'habano 2000|habano2000|habana 2000', 'Habano 2000', 'Hybride mis au point à Cuba dans les années 1990 pour remplacer le Corojo, abandonné ensuite sur l''île au profit du Criollo ''98. Sa parenté exacte est décrite de façons divergentes ; hors de Cuba, on l''emploie pour la cape, souvent sous toile.', 'Habano 2000', 'A hybrid developed in Cuba in the 1990s to replace Corojo, later abandoned on the island in favour of Criollo ''98. Its exact parentage is described in conflicting ways; outside Cuba it is used for wrappers, often grown under cloth.', 'Habano 2000', 'Híbrido desarrollado en Cuba en los años noventa para sustituir al Corojo, abandonado después en la isla en favor del Criollo ''98. Su parentesco exacto se describe de maneras divergentes; fuera de Cuba se emplea para la capa, a menudo cultivado bajo tela.', 'Habano 2000', 'Eine in den 1990er-Jahren in Kuba entwickelte Hybride als Ersatz für Corojo, auf der Insel später zugunsten von Criollo ''98 aufgegeben. Seine genaue Abstammung wird unterschiedlich beschrieben; außerhalb Kubas dient er für das Deckblatt, oft unter Tuch angebaut.', 'Habano 2000', '上世纪90年代在古巴培育的杂交品种，用来取代Corojo，后来在古巴被Criollo ''98取代。其确切亲本说法不一；在古巴境外多用作外包叶，常在遮阴布下种植。', 'هابانو 2000', 'هجين استُنبط في كوبا في تسعينيات القرن الماضي ليحلّ محل «كوروخو»، ثم تُرك في الجزيرة لصالح «كريولو 98». وتُوصف سلالته بطرق متباينة؛ وخارج كوبا يُستعمل للورقة الخارجية، وكثيرًا ما يُزرع تحت قماش التظليل.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'habano-2000');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'connecticut-shade', 'feuille', 'connecticut shade|connecticut-shade|capa connecticut', 'Connecticut Shade', 'Cape cultivée sous toile, d''abord dans la vallée du Connecticut, puis dans d''autres pays, notamment l''Équateur. Elle est fine, de teinte dorée à brun clair, et sert souvent à des cigares de force modérée.', 'Connecticut Shade', 'A wrapper grown under cloth, first in the Connecticut River valley and later in other countries, notably Ecuador. It is thin, golden to light brown in colour, and often used for cigars of moderate strength.', 'Connecticut Shade', 'Capa cultivada bajo tela, primero en el valle del Connecticut y después en otros países, en particular Ecuador. Es fina, de tono dorado a marrón claro, y se usa a menudo en puros de fuerza moderada.', 'Connecticut Shade', 'Ein unter Tuch angebautes Deckblatt, zuerst im Connecticut-Tal, später auch in anderen Ländern, vor allem in Ecuador. Es ist dünn, golden bis hellbraun und wird oft für Zigarren mittlerer Stärke verwendet.', '康涅狄格遮阴叶', '在遮阴布下种植的外包叶，起初产于康涅狄格河谷，后来也在其他国家种植，尤其是厄瓜多尔。叶片薄，色泽从金黄到浅棕，常用于浓度中等的雪茄。', 'كونيتيكت شيد', 'ورقة خارجية تُزرع تحت قماش التظليل، في وادي كونيتيكت أولًا ثم في بلدان أخرى، منها الإكوادور. وهي رقيقة بلون ذهبي إلى بني فاتح، وتُستعمل كثيرًا لسيجار متوسط القوة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'connecticut-shade');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'sumatra', 'feuille', 'sumatra|sumatras|capa sumatra', 'Sumatra', 'Type de cape dont la semence vient de l''île indonésienne de Sumatra, cultivée aujourd''hui notamment en Équateur sous toile. Sa feuille fine est de teinte dorée à brun clair.', 'Sumatra', 'A wrapper type whose seed comes from the Indonesian island of Sumatra, now grown notably in Ecuador under cloth. Its thin leaf is golden to light brown.', 'Sumatra', 'Tipo de capa cuya semilla procede de la isla indonesia de Sumatra, cultivada hoy en particular en Ecuador bajo tela. Su hoja fina tiene un tono dorado a marrón claro.', 'Sumatra', 'Ein Deckblatttyp, dessen Saatgut von der indonesischen Insel Sumatra stammt und der heute vor allem in Ecuador unter Tuch angebaut wird. Sein dünnes Blatt ist golden bis hellbraun.', '苏门答腊叶', '一种外包叶类型，种子源自印度尼西亚的苏门答腊岛，如今主要在厄瓜多尔于遮阴布下种植。叶片薄，呈金黄到浅棕色。', 'سومطرة', 'نوع من الورقة الخارجية تعود بذوره إلى جزيرة سومطرة الإندونيسية، ويُزرع اليوم في الإكوادور خصوصًا تحت قماش التظليل. ورقته رقيقة بلون ذهبي إلى بني فاتح.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'sumatra');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'havana-seed', 'feuille', 'havana seed|semences cubaines|graines cubaines|cuban seed', 'Havana Seed (semence cubaine)', 'Mention d''un tabac issu de semences d''origine cubaine mais cultivé ailleurs, par exemple dans le Connecticut ou en Amérique centrale. Elle décrit l''origine de la semence, non celle de la feuille, qui dépend du terroir.', 'Havana seed', 'A mention for tobacco grown from seed of Cuban origin but cultivated elsewhere, for example in Connecticut or Central America. It describes where the seed comes from, not the leaf, whose character depends on the terroir.', 'Semilla cubana', 'Mención de un tabaco nacido de semillas de origen cubano pero cultivado en otro lugar, por ejemplo en Connecticut o en Centroamérica. Describe el origen de la semilla, no el de la hoja, que depende del terruño.', 'Havana Seed (kubanisches Saatgut)', 'Angabe für Tabak aus Saatgut kubanischen Ursprungs, der anderswo angebaut wird, etwa in Connecticut oder Mittelamerika. Sie nennt die Herkunft des Saatguts, nicht die des Blattes, die vom Terroir abhängt.', '古巴种子（Havana Seed）', '指由古巴来源的种子在别处（如康涅狄格或中美洲）种出的烟草。它说明的是种子的来源，而不是烟叶的产地，烟叶的特点取决于风土。', 'بذور هافانا', 'إشارة إلى تبغ نشأ من بذور كوبية الأصل لكنه يُزرع في مكان آخر، مثل كونيتيكت أو أمريكا الوسطى. وهي تصف أصل البذرة لا أصل الورقة التي يحدد طابعها التربة والمناخ.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'havana-seed');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'piloto-cubano', 'feuille', 'piloto cubano|pilotos cubanos', 'Piloto Cubano', 'Variété de tripe d''origine cubaine, cultivée notamment en République dominicaine, dans la région du Cibao. On la trouve dans des assemblages dominicains, où elle fournit du corps à la tripe.', 'Piloto Cubano', 'A filler variety of Cuban origin, grown notably in the Dominican Republic, in the Cibao region. It is found in Dominican blends, where it contributes body to the filler.', 'Piloto Cubano', 'Variedad de tripa de origen cubano, cultivada en particular en la República Dominicana, en la región del Cibao. Se encuentra en mezclas dominicanas, donde aporta cuerpo a la tripa.', 'Piloto Cubano', 'Eine Einlagesorte kubanischen Ursprungs, die vor allem in der Dominikanischen Republik in der Region Cibao angebaut wird. Sie findet sich in dominikanischen Mischungen, wo sie der Einlage Körper verleiht.', '皮洛托古巴诺', '起源于古巴的叶芯品种，主要在多米尼加共和国的锡瓦奥（Cibao）地区种植。多米尼加的调配中可见到它，为叶芯带来酒体。', 'بيلوتو كوبانو', 'صنف حشوة كوبي الأصل يُزرع خصوصًا في الجمهورية الدومينيكية في منطقة سيباو. يوجد في تركيبات دومينيكية، حيث يمنح الحشوة جسمًا.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'piloto-cubano');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'pelo-de-oro', 'feuille', 'pelo de oro|pelo d''or', 'Pelo de Oro', 'Variété cubaine ancienne, dont le nom signifie cheveu d''or, délaissée à Cuba pour sa sensibilité au moho azul. Ses semences ont gagné d''autres pays, comme la République dominicaine et le Nicaragua, où elle est cultivée en petite quantité.', 'Pelo de Oro', 'An old Cuban variety whose name means golden hair, set aside in Cuba because of its susceptibility to blue mould. Its seeds have spread to other countries, such as the Dominican Republic and Nicaragua, where it is grown in small quantities.', 'Pelo de Oro', 'Variedad cubana antigua, cuyo nombre significa pelo de oro, abandonada en Cuba por su sensibilidad al moho azul. Sus semillas han pasado a otros países, como la República Dominicana y Nicaragua, donde se cultiva en pequeñas cantidades.', 'Pelo de Oro', 'Eine alte kubanische Sorte, deren Name goldenes Haar bedeutet und die in Kuba wegen ihrer Anfälligkeit für den Blauschimmel aufgegeben wurde. Ihr Saatgut gelangte in andere Länder, etwa in die Dominikanische Republik und nach Nicaragua, wo sie in kleinen Mengen angebaut wird.', '金发（Pelo de Oro）', '古巴的古老品种，名称意为金色头发，因易感霜霉病（moho azul）而在古巴被弃种。其种子传到了多米尼加共和国和尼加拉瓜等国，在那里少量种植。', 'بيلو دي أورو', 'صنف كوبي قديم يعني اسمه شعر الذهب، تُرك في كوبا لحساسيته للعفن الأزرق. وانتقلت بذوره إلى بلدان أخرى مثل الجمهورية الدومينيكية ونيكاراغوا، حيث يُزرع بكميات صغيرة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'pelo-de-oro');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'broadleaf', 'feuille', 'broadleaf|connecticut broadleaf|capa broadleaf', 'Broadleaf', 'Feuille large et épaisse, cultivée en plein soleil dans la vallée du Connecticut. Longuement fermentée, elle donne des capes brun foncé, de type maduro.', 'Broadleaf', 'A broad, thick leaf grown in full sun in the Connecticut River valley. Fermented at length, it yields dark brown wrappers of the maduro type.', 'Broadleaf', 'Hoja ancha y gruesa, cultivada a pleno sol en el valle del Connecticut. Fermentada largamente, da capas marrón oscuro de tipo maduro.', 'Broadleaf', 'Ein breites, dickes Blatt, das in voller Sonne im Connecticut-Tal wächst. Lange fermentiert, liefert es dunkelbraune Deckblätter vom Typ Maduro.', '宽叶烟（Broadleaf）', '在康涅狄格河谷全日照下种植的宽厚烟叶。经长时间发酵，可制成深棕色的马杜罗（maduro）型外包叶。', 'برودليف', 'ورقة عريضة سميكة تُزرع تحت الشمس الكاملة في وادي كونيتيكت. وبعد تخمير طويل تعطي أوراقًا خارجية بنية داكنة من نوع «مادورو».'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'broadleaf');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'mata-fina', 'feuille', 'mata fina', 'Mata Fina', 'Variété brésilienne cultivée dans l''État de Bahia, notamment dans la région de Recôncavo. Sa feuille sert à la cape, à la sous-cape et à la tripe, et donne une cape sombre et douce.', 'Mata Fina', 'A Brazilian variety grown in the state of Bahia, notably in the Recôncavo region. Its leaf is used for wrapper, binder and filler, and gives a dark, sweet wrapper.', 'Mata Fina', 'Variedad brasileña cultivada en el estado de Bahía, en particular en la región del Recôncavo. Su hoja se emplea para capa, subcapa y tripa, y da una capa oscura y dulce.', 'Mata Fina', 'Eine brasilianische Sorte, die im Bundesstaat Bahia angebaut wird, besonders in der Region Recôncavo. Ihr Blatt dient als Deckblatt, Umblatt und Einlage und ergibt ein dunkles, süßliches Deckblatt.', '马塔菲纳', '巴西品种，种植于巴伊亚州，尤其是雷孔卡沃（Recôncavo）地区。其叶片可用作外包叶、束叶和叶芯，外包叶颜色深、风味偏甜。', 'ماتا فينا', 'صنف برازيلي يُزرع في ولاية باهيا، خصوصًا في منطقة ريكونكافو. تُستعمل ورقته للورقة الخارجية والغلاف الداخلي والحشوة، وتعطي ورقة خارجية داكنة حلوة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'mata-fina');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'palillo', 'atelier', 'palillo|palillos', 'Palillo', 'Nom cubain de la nervure centrale de la feuille de tabac. C''est elle que retire le despalillo, car une côte dure gênerait le roulage et le tirage.', 'Palillo', 'The Cuban name for the central rib of the tobacco leaf. It is what the despalillo removes, since a hard rib would hamper rolling and the draw.', 'Palillo', 'Nombre cubano de la vena central de la hoja de tabaco. Es lo que quita el despalillo, pues una vena dura estorbaría el liado y el tiro.', 'Palillo', 'Der kubanische Name für die Mittelrippe des Tabakblatts. Sie wird beim Despalillo entfernt, denn eine harte Rippe würde das Rollen und den Zug behindern.', '叶梗（palillo）', '古巴人对烟叶中央主脉的称呼。去梗（despalillo）去掉的就是它，因为坚硬的叶脉会妨碍卷制和抽吸。', 'باليّو', 'الاسم الكوبي للعرق المركزي لورقة التبغ. وهو ما تنزعه عملية «ديسبياليو»، لأن العرق القاسي يعيق اللفّ والسحب.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'palillo');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'escogida', 'atelier', 'escogida|escogidas', 'Escogida', 'Le tri des feuilles sèches selon leur taille, leur couleur et leur texture, mot cubain qui désigne aussi le local où il se fait. Elle suit le séchage et sépare notamment les feuilles de cape de celles de tripe.', 'Escogida', 'The sorting of dried leaves by size, colour and texture, a Cuban word that also names the building where it is done. It follows curing and separates, among other things, wrapper leaves from filler leaves.', 'Escogida', 'La clasificación de las hojas secas según su tamaño, color y textura, palabra cubana que también nombra el local donde se hace. Sigue al curado y separa, entre otras, las hojas de capa de las de tripa.', 'Escogida', 'Das Sortieren der getrockneten Blätter nach Größe, Farbe und Textur; ein kubanisches Wort, das auch das Gebäude bezeichnet, in dem es geschieht. Es folgt auf die Trocknung und trennt unter anderem Deckblätter von Einlageblättern.', '分级车间（escogida）', '按大小、颜色和质地给干燥烟叶分级，这是古巴用词，也指进行分级的场所。分级在晾干之后，其中包括把外包叶与叶芯用叶分开。', 'إسكوخيدا', 'فرز الأوراق الجافة بحسب حجمها ولونها وملمسها، وهي كلمة كوبية تسمّي أيضًا المكان الذي يتم فيه الفرز. تأتي بعد التجفيف وتفصل، من جملة ما تفصل، أوراق الورقة الخارجية عن أوراق الحشوة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'escogida');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'rezago', 'atelier', 'rezago|rezagos', 'Rezago', 'Dans le vocabulaire du tri, l''étape où les feuilles écartées au premier classement sont reprises et reclassées par taille, couleur et qualité, ou ces feuilles elles-mêmes. Le sens exact varie d''une fabrique à l''autre.', 'Rezago', 'In sorting vocabulary, the stage or the leaves set aside at the first grading that are taken up again and reclassified by size, colour and quality. The exact sense varies from one factory to another.', 'Rezago', 'En el vocabulario de la clasificación, la etapa o las hojas apartadas en la primera clasificación que se retoman y se reclasifican por tamaño, color y calidad. El sentido exacto varía de una fábrica a otra.', 'Rezago', 'Im Vokabular der Sortierung die Stufe oder die beim ersten Sortieren beiseitegelegten Blätter, die erneut aufgegriffen und nach Größe, Farbe und Qualität neu eingeteilt werden. Die genaue Bedeutung schwankt von Fabrik zu Fabrik.', '回选（rezago）', '分级用语中，指把初次分级时挑出的烟叶重新拿来，按大小、颜色和品质再次分类的环节或这些烟叶。确切含义因工厂而异。', 'ريزاغو', 'في مصطلحات الفرز، المرحلة أو الأوراق المستبعدة في التصنيف الأول التي تُستعاد وتُعاد تصنيفها بحسب الحجم واللون والجودة. ويختلف المعنى الدقيق من مصنع إلى آخر.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'rezago');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'escaparate', 'atelier', 'escaparate|escaparates', 'Escaparate', 'Selon Habanos, l''endroit où les cigares finis se reposent un temps avant d''être bagués et mis en boîte. Ils y retrouvent un taux d''humidité homogène.', 'Escaparate', 'According to Habanos, the place where finished cigars rest for a time before being banded and boxed. There they regain an even moisture level.', 'Escaparate', 'Según Habanos, el lugar donde los puros terminados reposan un tiempo antes de anillarse y encajarse. Allí recuperan una humedad homogénea.', 'Escaparate', 'Laut Habanos der Ort, an dem fertige Zigarren eine Zeit lang ruhen, bevor sie mit Binde versehen und in Kisten gepackt werden. Dort finden sie zu einer gleichmäßigen Feuchte zurück.', '雪茄静置室（escaparate）', '据Habanos介绍，成品雪茄在上烟标和装盒之前静置一段时间的场所，雪茄在这里恢复均匀的湿度。', 'إسكاباراتي', 'بحسب «هابانوس»، المكان الذي تستريح فيه السيجارات الجاهزة مدة قبل أن تُوضع عليها الحلقة وتُعبّأ في العلب. وفيه تستعيد رطوبة متجانسة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'escaparate');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'yagua', 'atelier', 'yagua|yaguas', 'Yagua', 'La gaine fibreuse du palmier royal, dont on enveloppe à Cuba les balles de feuilles pour la garde et le transport. Elle laisse respirer le tabac tout en le protégeant.', 'Yagua', 'The fibrous sheath of the royal palm, used in Cuba to wrap bales of leaves for storage and transport. It lets the tobacco breathe while protecting it.', 'Yagua', 'La vaina fibrosa de la palma real, con la que se envuelven en Cuba los fardos de hojas para el almacenamiento y el transporte. Deja respirar al tabaco a la vez que lo protege.', 'Yagua', 'Die faserige Scheide der Königspalme, mit der in Kuba Ballen von Blättern für Lagerung und Transport umhüllt werden. Sie lässt den Tabak atmen und schützt ihn zugleich.', '棕榈鞘（yagua）', '王棕的纤维质叶鞘，古巴用它包裹成捆的烟叶，用于存放和运输。它既保护烟叶，又让烟叶能够透气。', 'ياغوا', 'الغلاف الليفي لنخلة الملك، تُلفّ به في كوبا حزم الأوراق للتخزين والنقل. فهو يسمح للتبغ بالتنفس ويحميه في الوقت نفسه.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'yagua');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'ligada', 'atelier', 'ligada|ligadas|ligador|ligadores', 'Ligada', 'En Cuba, le dosage des feuilles qui composent la tripe d''une vitola, préparé par le ligador avant d''être confié aux torcedores. C''est la recette de la tripe, distincte du choix de la cape.', 'Ligada', 'In Cuba, the proportioning of the leaves that make up the filler of a vitola, prepared by the ligador before being handed to the torcedores. It is the recipe for the filler, separate from the choice of wrapper.', 'Ligada', 'En Cuba, la dosificación de las hojas que componen la tripa de una vitola, preparada por el ligador antes de entregarse a los torcedores. Es la receta de la tripa, distinta de la elección de la capa.', 'Ligada', 'In Kuba die Dosierung der Blätter, die die Einlage einer Vitola bilden, vom Ligador vorbereitet und dann den Torcedores übergeben. Sie ist das Rezept der Einlage, getrennt von der Wahl des Deckblatts.', '配叶（ligada）', '在古巴，指构成某一尺寸雪茄叶芯的各种烟叶的配比，由配叶工（ligador）备好后交给卷烟师。它是叶芯的配方，与外包叶的选择是两回事。', 'ليغادا', 'في كوبا، تحديد نِسَب الأوراق التي تؤلف حشوة مقاس معيّن، يُعدّها «ليغادور» قبل تسليمها إلى «التورسيدورس». وهي وصفة الحشوة، ومنفصلة عن اختيار الورقة الخارجية.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'ligada');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'moldes', 'atelier', 'molde|moldes|moules en bois|pressage des cigares', 'Moldes', 'Les moules en bois où le torcedor place les cigares roulés pour les presser. Le cigare y prend sa forme et sa section régulière avant de recevoir sa tête.', 'Moulds', 'The wooden moulds in which the torcedor places the rolled cigars to press them. The cigar takes its shape and even section there before its head is finished.', 'Moldes', 'Los moldes de madera donde el torcedor coloca los puros liados para prensarlos. El puro toma allí su forma y su sección regular antes de recibir la cabeza.', 'Formen', 'Die Holzformen, in die der Torcedor die gerollten Zigarren zum Pressen legt. Die Zigarre erhält darin ihre Form und ihren gleichmäßigen Querschnitt, bevor ihr Kopf fertiggestellt wird.', '木模（molde）', '卷烟师放入卷好的雪茄进行压制的木制模具。雪茄在其中成形并获得均匀的截面，之后才封上头部。', 'القوالب', 'القوالب الخشبية التي يضع فيها «التورسيدور» السيجارات الملفوفة لكبسها. يكتسب السيجار فيها شكله ومقطعه المنتظم قبل أن يُنجَز رأسه.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'moldes');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'curado', 'atelier', 'curado|séchage à l''air|séchage des feuilles', 'Curado (séchage à l''air)', 'Le séchage des feuilles à l''air libre dans la casa de tabaco, qui dure quelques semaines. La feuille y passe du vert au jaune puis au brun, par oxydation lente, avant l''escogida et la fermentation.', 'Air-curing', 'The drying of leaves in open air in the casa de tabaco, which lasts a few weeks. The leaf turns from green to yellow and then brown through slow oxidation, before the escogida and fermentation.', 'Curado', 'El secado de las hojas al aire libre en la casa de tabaco, que dura unas semanas. La hoja pasa del verde al amarillo y luego al marrón por oxidación lenta, antes de la escogida y la fermentación.', 'Lufttrocknung', 'Das Trocknen der Blätter an der Luft in der Casa de tabaco, das einige Wochen dauert. Das Blatt wechselt dabei durch langsame Oxidation von Grün über Gelb zu Braun, bevor Escogida und Fermentation folgen.', '风干', '烟叶在烟叶晾房（casa de tabaco）中自然风干，历时数周。烟叶经缓慢氧化由绿变黄再变褐，之后才进入分级和发酵。', 'التجفيف الهوائي', 'تجفيف الأوراق في الهواء الطلق داخل «كاسا دي تاباكو»، ويستغرق أسابيع قليلة. وتتحول الورقة من الأخضر إلى الأصفر ثم البني بتأكسد بطيء، قبل الفرز والتخمير.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'curado');

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'lexique', l.`id`, f.champ, g.lang, SHA1(IF(f.champ = 'terme', l.`terme`, l.`definition`)), 'machine', NOW()
  FROM `lexique` l
  JOIN (SELECT 'terme' champ UNION ALL SELECT 'definition') f
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') g
 WHERE l.`id` IN ('moisissure', 'remise-en-etat', 'acclimatation', 'humidite-relative', 'humidificateur', 'quarantaine', 'vieillissement', 'lasioderma', 'code-de-boite', 'numero-de-serie', 'contrefacon', 'marque-homonyme', 'corojo', 'criollo', 'habano-2000', 'connecticut-shade', 'sumatra', 'havana-seed', 'piloto-cubano', 'pelo-de-oro', 'broadleaf', 'mata-fina', 'palillo', 'escogida', 'rezago', 'escaparate', 'yagua', 'ligada', 'moldes', 'curado')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 316';
INSERT INTO `moderation_log` (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES (NULL, 'migration 316', 'systeme', 'lexique_enrichi', 'systeme', 0, 'Lexique : 30 termes ajoutes (56 -> 86)');

-- Contrôle : des 1 partout.
SELECT
  (SELECT COUNT(*) FROM `lexique`) = 86 AS `termes`,
  (SELECT COUNT(*) FROM `lexique` WHERE `terme_ar` IS NULL OR `definition_zh` IS NULL OR `definition_de` IS NULL) = 0 AS `traduits`;
